package database

func MessageSharingMigrations() []string {
	return []string{
		`ALTER TABLE messages ADD COLUMN IF NOT EXISTS sharing_limits JSONB`,
		`ALTER TABLE message_forward_operations ADD COLUMN IF NOT EXISTS mode TEXT NOT NULL DEFAULT 'native', ADD COLUMN IF NOT EXISTS content_variant TEXT NOT NULL DEFAULT 'original', ADD COLUMN IF NOT EXISTS sharing_limits JSONB`,
		`DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='messages_sharing_limits_valid') THEN ALTER TABLE messages ADD CONSTRAINT messages_sharing_limits_valid CHECK(sharing_limits IS NULL OR (jsonb_typeof(sharing_limits)='object' AND sharing_limits ? 'max_chats' AND sharing_limits ? 'max_groups' AND sharing_limits->>'max_chats' IS NOT NULL AND sharing_limits->>'max_groups' IS NOT NULL AND jsonb_typeof(sharing_limits->'max_chats')='number' AND jsonb_typeof(sharing_limits->'max_groups')='number' AND sharing_limits->>'max_chats' IN ('1','5') AND sharing_limits->>'max_groups' IN ('1','5') AND (sharing_limits->>'max_groups')::int<=(sharing_limits->>'max_chats')::int)); END IF; END $$`,
		`DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='message_forward_operations_sharing_valid') THEN ALTER TABLE message_forward_operations ADD CONSTRAINT message_forward_operations_sharing_valid CHECK(mode IN ('native','copy') AND content_variant IN ('original','audio_document') AND (content_variant='original' OR mode='copy') AND (sharing_limits IS NULL OR (jsonb_typeof(sharing_limits)='object' AND sharing_limits ? 'max_chats' AND sharing_limits ? 'max_groups' AND sharing_limits->>'max_chats' IS NOT NULL AND sharing_limits->>'max_groups' IS NOT NULL AND jsonb_typeof(sharing_limits->'max_chats')='number' AND jsonb_typeof(sharing_limits->'max_groups')='number' AND sharing_limits->>'max_chats' IN ('1','5') AND sharing_limits->>'max_groups' IN ('1','5') AND (sharing_limits->>'max_groups')::int<=(sharing_limits->>'max_chats')::int))); END IF; END $$`,
		`CREATE OR REPLACE FUNCTION clarin_min_message_sharing_limits(old_value JSONB,new_value JSONB) RETURNS JSONB LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN old_value IS NULL THEN new_value WHEN new_value IS NULL THEN old_value ELSE jsonb_build_object('max_chats',LEAST((old_value->>'max_chats')::int,(new_value->>'max_chats')::int),'max_groups',LEAST((old_value->>'max_groups')::int,(new_value->>'max_groups')::int)) END $$`,
	}
}
